function pricingPage({countryCode,countryName,rawPrice,currency,monthlyFormatted,paymentMethods,taxPct,taxName}){const S={USD:'$',GBP:'£',EUR:'€',AED:'AED ',SAR:'SAR ',KWD:'KD ',QAR:'QR ',BHD:'BD ',OMR:'OMR ',JOD:'JOD ',EGP:'EGP ',MAD:'MAD ',TND:'TND ',DZD:'DZD ',INR:'₹',PKR:'₨',BDT:'৳',LKR:'LKR ',IDR:'IDR ',MYR:'RM ',PHP:'₱',THB:'฿',SGD:'S$',HKD:'HK$',JPY:'¥',KRW:'₩',CNY:'¥',TWD:'NT$',TRY:'₺',RUB:'₽',UAH:'₴',PLN:'zł ',CZK:'Kč ',HUF:'Ft ',SEK:'kr ',NOK:'kr ',DKK:'kr ',CHF:'CHF ',RON:'lei ',BGN:'лв ',BRL:'R$ ',MXN:'$',ARS:'$',COP:'$',CLP:'$',PEN:'S/ ',NGN:'₦',GHS:'GH₵',KES:'KSh ',ZAR:'R ',TZS:'TSh ',UGX:'USh ',CAD:'CA$',AUD:'A$',NZD:'NZ$'},fmt(a,c){const n=Math.round(a);return(S[c]||(''+c+' '))+n};return{countryCode,countryName,rawPrice,currency,monthlyFormatted,paymentMethods,taxPct,taxName,billing:'monthly',openSwitcher:false,countrySearch:'',_allData:(()=>{const d={!!$allDataJson!!};if(d.GLOBAL)d.GLOBAL.name='Other countries';return d})(),filteredCountries(){return Object.entries(this._allData).filter(([c,d])=>c!=='GLOBAL'&&(!this.countrySearch||d.name.toLowerCase().includes(this.countrySearch.toLowerCase()))).map(([code,d])=>({code,name:d.name,lang:d.lang||'en'}))},flagEmoji(c){if(!c||c==='GLOBAL')return'🌍';try{return[...c].map(x=>String.fromCodePoint(x.toUpperCase().charCodeAt(0)+127397)).join('')}catch(e){return'🏳'}},langName(l){const m={en:'English',ar:'العربية',fr:'Français',de:'Deutsch',es:'Español',pt:'Português',tr:'Türkçe',ru:'Русский',zh:'中文',ja:'日本語',ko:'한국어',id:'Indonesia',hi:'हिन्दी',ms:'Melayu',th:'ภาษาไทย'};return m[l]||'English'},get annualPerMonthFormatted(){return this.fmt(this.rawPrice*10/12,this.currency)},get taxTotalFormatted(){return this.fmt(this.rawPrice+(this.taxPct?Math.round(this.rawPrice*this.taxPct/100):0),this.currency)},switchCountry(code){const d=this._allData[code];if(!d)return;Object.assign(this,{countryCode:code,countryName:d.name,monthlyFormatted:d.monthly,rawPrice:d.price,currency:d.currency,paymentMethods:d.methods||[],taxPct:d.taxPct||0,taxName:d.taxName||'VAT',openSwitcher:false,countrySearch:''});fetch('/pricing/set-country',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]')?.content||'','Accept':'application/json'},body:JSON.stringify({country_code:code)}).catch(()=>{})},renderPaymentMethods(){const L={stripe:'Stripe',paypal:'PayPal',mada:'Mada',fawry:'Fawry',razorpay:'Razorpay',moyasar:'Moyasar',paymob:'Paymob',telr:'Telr',tap:'Tap Payments',iyzico:'Iyzico',pagseguro:'PagSeguro'};return(this.paymentMethods||[]).map(m=>`<span class="vp-method">${L[m]||m}</span>`).join('')}}}
</script>@endpush
